const src = wb.getWorksheet('Imported Data'), dst = wb.getWorksheet('Items Older than 30 days');
const vals = src.getRange('A1:I14').getValues();
const maxD = Math.max(...vals.slice(1).map(r => r[4]));
const picked = vals.slice(1).filter(r => r[4] < maxD - 30);
log('max', maxD, 'picked', picked.length);
const hdr = [vals[0], ...picked];
hdr.forEach((r, i) => r.forEach((v, c) => { if (v !== null && v !== undefined && v !== '') dst.getRange('A1:I50').getCell(i, c).setValue(typeof v === 'string' ? "'" + v : v); }));
dst.getRange(`E2:E${hdr.length}`).getStyle().setNumberFormat('dd/mm/yyyy');
dst.getRange('Z:Z').delete({ shift: 'left' } as any);
log(dst.getUsedRange().getA1());
log(dst.getRange('A1:I3'));
log(dst.getRange('A1:I2').getValues());
log(dst.getRange('E2').getCell());
log(dst.getRange('T1:Z2'));

